{
  "title": "济南本地历史一本院校计算机相关专业考研长线学习计划（目标初试2029年）",
  "goal": "面向济南本地历史本科一批院校的计算机相关专业，以2029年考研初试为目标，重点准备计算机科学与技术、计算机技术、软件工程、人工智能、网络与信息安全等方向，按数学、英语、政治和计算机学科专业基础或院校自命题科目分阶段推进，最终以目标年度招生目录和报考条件为准。",
  "summary": "本次推荐以济南本地高校为范围，结合已核验的官方历史招生资料，给出济南大学、山东师范大学、山东财经大学三所候选。三校均有计算机相关硕士培养方向或招生专业，且可查见历史本科一批招生事实：济南大学为2016年山东普通本科一批及济南走读一批，山东师范大学为2016年河北一批、天津一批B类，山东财经大学为2016年山东普通本科一批，但均只作历史层次参考，不代表所有专业、所有省份或未来批次。目标初试年份为2029年，招生入学年度为2030年；目前教育部及研招网尚未公布该年度初试日期，故按12月第三个周六暂定规划为2029年12月15日，计划截止至2029年12月14日，正式日期和报名要求待官方发布后核实。专业目录、考试科目、报考资格、实际培养校区均需以目标年度官方通知为准。建议大一先巩固英语与数学，了解计算机学科专业基础统考与自命题差异，大二大三强化计算机基础与项目实践，大四前完成真题与模拟。",
  "dateStatus": "estimated",
  "examDate": "",
  "examSourceUrl": "",
  "sourceUrls": [
    "https://yanzhao.ujn.edu.cn/zsml/enterViewZsml?nd=2027#1",
    "https://yz.ujn.edu.cn/info/1032/3944.htm#1#1#1",
    "https://admission.ujn.edu.cn/info/1024/2532.htm?_x_output_type_b6db407c4_=embedded_pdf#2#1",
    "https://xxgk.ujn.edu.cn/__local/2/D4/61/18EB3CE24CAB055ADA7C69E792C_BBC62789_218FF.pdf#2#1",
    "https://ischool.sdnu.edu.cn/info/1288/16435.htm#1",
    "http://www.xxgk.sdnu.edu.cn/info/1011/3358.htm#156#111",
    "https://cie.sdnu.edu.cn/info/1072/1924.htm#1",
    "https://sais.sdufe.edu.cn/info/1010/2374.htm",
    "http://news.sdufe.edu.cn/info/1071/20616.htm"
  ],
  "recommendationNotice": "推荐范围限定为济南本地、有历史本科一批招生事实且开设计算机相关硕士方向的院校，共三所。历史层次仅依据学校官方往年招生资料，作择校参考，不代表2029年初试、2030年入学的报考资格或批次要求。目标年度专业目录、考试科目、招生人数、报考限制、实际培养校区均待官方公布后核实，不承诺录取概率。",
  "recommendations": [
    {
      "name": "济南大学",
      "reason": "济南本地高校，学校官方2027年硕士招生专业目录显示设有计算机科学与技术、计算机技术、人工智能等全日制方向，信息科学与工程学院计算机类本科培养地点为主校区。该校2016年在山东有普通本科一批及济南走读本科一批录取记录，可作历史一本参考层次。建议作为济南地区重点候选，目标年度专业目录、考试科目和报考限制待核实。",
      "sourceUrl": "https://yanzhao.ujn.edu.cn/zsml/enterViewZsml?nd=2027#1",
      "location": {
        "province": "山东",
        "city": "济南",
        "campus": "信息科学与工程学院计算机类本科培养地点为主校区（济南市南辛庄西路336号）；硕士培养方案未标地点，2029级安排待核实。",
        "sourceUrl": "https://admission.ujn.edu.cn/info/1024/2532.htm?_x_output_type_b6db407c4_=embedded_pdf#2#1"
      },
      "criteriaEvidence": [
        {
          "criterion": "一本（历史参考）",
          "explanation": "该校2016年山东省普通文理录取统计列有“本科一批普通”及济南走读本科一批次，适用2016年山东省，仅作历史招生层次参考；不表示所有专业、所有省份同一批次。目标年度报考资格与批次要求待官方公布后核实。",
          "sourceUrl": "https://xxgk.ujn.edu.cn/__local/2/D4/61/18EB3CE24CAB055ADA7C69E792C_BBC62789_218FF.pdf#2#1"
        }
      ]
    },
    {
      "name": "山东师范大学",
      "reason": "济南本地高校，信息科学与工程学院及相关学院开设计算机技术、软件工程等全日制专业学位方向，本科招生网设计算机科学与技术专业，长清校区为计算机科学与技术专业办学地点。该校2016年省外录取统计中河北为本科一批、天津为本科一批B类，可作历史一本参考。山东本省该表未涉及，目标年度要求待核实。",
      "sourceUrl": "https://ischool.sdnu.edu.cn/info/1288/16435.htm#1",
      "location": {
        "province": "山东",
        "city": "济南",
        "campus": "计算机科学与技术专业办学地点为长清校区（济南市长清区大学科技园大学路1号）；目标年度校区安排待核实。",
        "sourceUrl": "http://www.xxgk.sdnu.edu.cn/info/1011/3358.htm#156#111"
      },
      "criteriaEvidence": [
        {
          "criterion": "一本（历史参考）",
          "explanation": "该校2016年省外普通专业录取统计中，河北为本科一批、天津为本科一批B类，适用2016年上述省份，仅作历史一本参考；北京、山西等地批次不同，不能泛称全校所有省份一本。山东本省该表未涉及，目标年度要求待核实。",
          "sourceUrl": "https://cie.sdnu.edu.cn/info/1072/1924.htm#1"
        }
      ]
    },
    {
      "name": "山东财经大学",
      "reason": "济南本地高校，计算机与人工智能学院及智能科学与技术学院相关专业涉及计算机软件与理论、计算机应用技术、数字媒体技术、电子信息等方向；2026年招生考试起部分计算机类专业第四单元科目调整为计算机学科专业基础。学校2016年在山东省内普通本科一批招生，同时有本科二批等项目，可作历史一本参考。实际培养校区、目标年度目录和报考资格待核实。",
      "sourceUrl": "https://sais.sdufe.edu.cn/info/1010/2374.htm",
      "location": {
        "province": "山东",
        "city": "济南",
        "campus": "所推荐计算机类专业实际培养校区待核实；学校位于济南，2029级具体校区以入学当年官方安排为准。",
        "sourceUrl": "http://news.sdufe.edu.cn/info/1071/20616.htm"
      },
      "criteriaEvidence": [
        {
          "criterion": "一本（历史参考）",
          "explanation": "该校官方2016年8月29日招生总结记载在山东省内普通本科一批招生，同时存在本科二批、中外合作等项目，适用2016年山东省，仅作历史一本参考层次，不能称所有专业都在一批。目标年度要求待核实。",
          "sourceUrl": "http://news.sdufe.edu.cn/info/1071/20616.htm"
        }
      ]
    }
  ],
  "tasks": [
    {
      "title": "建立考研长线档案：确认目标初试年份为2029年，了解济南大学、山东师范大学、山东财经大学等候选院校的计算机相关专业，记录官方信息待核实清单。",
      "stage": "信息核对与基础",
      "dueDate": "2026-10-07"
    },
    {
      "title": "英语词汇与语法打底：制定每日词汇计划，复习基本句法；数学从高等数学一元函数微积分起步，整理公式与基础错题。",
      "stage": "信息核对与基础",
      "dueDate": "2026-12-24"
    },
    {
      "title": "继续数学基础：学习线性代数入门与概率论基本概念；计算机方向先熟悉C语言、数据结构基本概念，了解计算机学科专业基础统考范围。",
      "stage": "信息核对与基础",
      "dueDate": "2027-03-11"
    },
    {
      "title": "完成第一轮英语基础语法与长难句训练，数学覆盖高等数学主干；开始数据结构与计算机网络入门学习，定期查看候选院校官网招生动态。",
      "stage": "信息核对与基础",
      "dueDate": "2027-05-28"
    },
    {
      "title": "暑期系统强化：数学集中攻克高等数学、线性代数、概率论基础题型；英语加强阅读；计算机专业课学习数据结构与操作系统。",
      "stage": "系统学习与强化",
      "dueDate": "2027-08-13"
    },
    {
      "title": "数学进入强化第二轮，配合习题册整理错题；计算机组成原理与操作系统同步推进；英语开始较早年份真题阅读训练。",
      "stage": "系统学习与强化",
      "dueDate": "2027-10-30"
    },
    {
      "title": "寒假集中突破：梳理数据结构、操作系统、计算机网络知识框架，数学错题重做，英语继续长难句和阅读精读。",
      "stage": "系统学习与强化",
      "dueDate": "2028-01-16"
    },
    {
      "title": "完成计算机核心课程第一轮系统学习，数学强化收尾并建立综合题思路；核对目标院校专业目录、考试科目和参考书目是否更新。",
      "stage": "系统学习与强化",
      "dueDate": "2028-04-02"
    },
    {
      "title": "进入真题训练：数学开始历年真题分模块练习，英语精读真题阅读，计算机专业课按章节做真题并标记薄弱知识点。",
      "stage": "真题训练与查漏",
      "dueDate": "2028-06-19"
    },
    {
      "title": "真题强化阶段：数学套卷与错题并行，计算机专业课完成第二轮真题，政治开始基础知识点学习，英语增加写作练习。",
      "stage": "真题训练与查漏",
      "dueDate": "2028-09-04"
    },
    {
      "title": "数学按套卷限时训练，专业课进行模拟与背诵，英语打磨作文模板，政治完成选择题训练并整理易错点。",
      "stage": "真题训练与查漏",
      "dueDate": "2028-11-21"
    },
    {
      "title": "寒假查漏补缺：集中处理数学薄弱章节和计算机专业课难点，英语作文反复修改，政治复习核心考点。",
      "stage": "真题训练与查漏",
      "dueDate": "2029-02-07"
    },
    {
      "title": "关注目标年度招生简章与专业目录发布情况，数学进行综合模拟，专业课进入背诵与真题复盘，保持英语阅读和写作手感。",
      "stage": "模拟冲刺与调整",
      "dueDate": "2029-04-25"
    },
    {
      "title": "暑期冲刺：数学套卷与错题回顾，计算机专业课模拟考试，政治强化背诵，英语真题二刷和作文成稿。",
      "stage": "模拟冲刺与调整",
      "dueDate": "2029-07-12"
    },
    {
      "title": "大四上学期全科模拟：按暂定考试季时间安排整卷训练，调整答题节奏；核对报名、确认、准考证等官方通知要求。",
      "stage": "模拟冲刺与调整",
      "dueDate": "2029-09-27"
    },
    {
      "title": "考前最后一天：核对证件与考试用品，回顾数学、英语、政治、计算机学科专业基础的错题和知识框架，调整作息，按正式通知参加考试。",
      "stage": "模拟冲刺与调整",
      "dueDate": "2029-12-14"
    }
  ]
}
